SELECT quote.id AS id, 'Quotation' AS type, quote.quotation_code AS code, (quote.total_amount - quote.discount + quote.total_vat) AS amount, quote.quotation_date AS date, quote.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = quote.created_by) AS createdBy, quote.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = quote.modified_by) AS modifiedBy, quote.status AS statusNum FROM quotations quote WHERE 1
AND DATE(quote.quotation_date) >= DATE(#{filter.dateFrom}) AND DATE(quote.quotation_date) <= DATE(#{filter.dateTo})
AND quote.created_by = #{filter.createBy}
AND branch_id IN
#{id}
ORDER BY quote.quotation_code ASC, quote.created ASC

SELECT so.id AS id, 'Invoice' AS type, so.so_code AS code, (so.total_amount - so.discount + so.total_vat) AS amount, so.order_date AS date, so.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = so.created_by) AS createdBy, so.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = so.modified_by) AS modifiedBy, status AS statusNum FROM sales_orders so WHERE so.is_pos = 0
AND DATE(so.order_date) >= DATE(#{filter.dateFrom}) AND DATE(so.order_date) <= DATE(#{filter.dateTo})
AND so.created_by = #{filter.createBy}
AND branch_id IN
#{id}
ORDER BY created ASC

SELECT saleOrder.id AS id, 'Sale Order' AS type, saleOrder.order_code AS code, (saleOrder.total_amount - saleOrder.discount + saleOrder.total_vat) AS amount, saleOrder.order_date AS date, saleOrder.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = saleOrder.created_by) AS createdBy, saleOrder.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = saleOrder.modified_by) AS modifiedBy, saleOrder.status AS statusNum FROM orders saleOrder WHERE 1
AND DATE(saleOrder.order_date) >= DATE(#{filter.dateFrom}) AND DATE(saleOrder.order_date) <= DATE(#{filter.dateTo})
AND saleOrder.created_by = #{filter.createBy}
AND branch_id IN
#{id}
ORDER BY order_code, created ASC

SELECT so.id AS id, 'Invoice POS' AS type, so.so_code AS code, (so.total_amount - so.discount + so.total_vat) AS amount, so.order_date AS date, so.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = so.created_by) AS createdBy, so.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = so.modified_by) AS modifiedBy, CASE WHEN so.status = -1 THEN "Modified" WHEN so.status = 0 THEN "Void" WHEN (so.status = 1 OR so.status = 2) THEN "Prior" ELSE "Latest" END AS status FROM sales_orders so WHERE so.is_pos = 1
AND DATE(so.order_date) >= DATE(#{filter.dateFrom}) AND DATE(so.order_date) <= DATE(#{filter.dateTo})
AND so.created_by = #{filter.createBy}
AND so.branch_id IN
#{id}
ORDER BY so.created ASC;

SELECT cm.id AS id, 'Credit Memo' AS type, cm.cm_code AS code, (total_amount - discount + total_vat) AS amount, cm.order_date AS date, cm.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = cm.created_by) AS createdBy, cm.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = cm.modified_by) AS modifiedBy, status AS statusNum FROM credit_memos cm WHERE 1
AND DATE(cm.order_date) >= DATE(#{filter.dateFrom}) AND DATE(cm.order_date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND cm.created_by = #{filter.createBy} ;

SELECT dv.id AS id, 'Delivery' AS type, dv.code AS code, dv.date AS date, 0 AS amount, dv.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = dv.created_by) AS createdBy, dv.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = dv.modified_by) AS modifiedBy, status AS statusNum FROM deliveries dv WHERE 1
AND DATE(dv.date) >= DATE(#{filter.dateFrom}) AND DATE(dv.date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND dv.created_by = #{filter.createBy} ;

SELECT rp.id AS id, 'Receive Payment' AS type, rp.reference AS code, rp.date AS date, (SELECT IFNULL(SUM(paid), 0) FROM receive_payment_details WHERE receive_payment_id = rp.id ) AS amount, rp.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = rp.created_by) AS createdBy, rp.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = rp.modified_by ) AS modifiedBy, is_active AS statusNum FROM receive_payments rp WHERE 1
AND DATE(rp.date) >= DATE(#{filter.dateFrom}) AND DATE(rp.date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND rp.created_by = #{filter.createBy}

SELECT adj.id AS id, 'Adjustment' AS type, adj.reference AS code, adj.date AS date, adj.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = adj.created_by) AS createdBy, adj.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = adj.modified_by) AS modifiedBy, status AS statusNum FROM cycle_products adj WHERE 1
AND DATE(adj.date) >= DATE(#{filter.dateFrom}) AND DATE(adj.date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND adj.created_by = #{filter.createBy} ;

SELECT tf.id AS id, 'Transfer Order' AS type, tf.to_code AS code, tf.order_date AS date, tf.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = tf.created_by) AS createdBy, tf.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = tf.modified_by) AS modified_name, -- CASE -- WHEN status = -1 THEN "Modified" -- WHEN status = 0 THEN "Void" -- WHEN (status = 2 OR status = 3) THEN "Prior" -- ELSE "Latest" -- END AS status status AS statusNum FROM transfer_orders tf WHERE 1
AND DATE(tf.order_date) >= DATE(#{filter.dateFrom}) AND DATE(tf.order_date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND tf.created_by = #{filter.createBy} ;

SELECT pr.id AS id, 'Purchase Order' AS type, pr.pr_code AS code, (pr.total_amount + pr.total_vat) AS amount, pr.order_date AS date, pr.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.created_by) AS createdBy, pr.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.modified_by) AS modifiedBy, -- CASE -- WHEN status = -1 THEN "Modified" -- WHEN status = 0 THEN "Void" -- WHEN (status = 2 OR status = 3) THEN "Prior" -- ELSE "Latest" -- END AS status status AS statusNum FROM purchase_requests pr WHERE 1
AND DATE(pr.order_date) >= DATE(#{filter.dateFrom}) AND DATE(pr.order_date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND pr.created_by = #{filter.createBy} ;

SELECT po.id AS id, 'Purchase Bill' AS type, po.po_code AS code, (po.total_amount - po.discount_amount + po.total_vat) AS amount, po.order_date AS date, po.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = po.created_by) AS createdBy, po.modified AS modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = po.modified_by) AS modifiedBy, status AS statusNum FROM purchase_orders po WHERE 1
AND DATE(po.order_date) >= DATE(#{filter.dateFrom}) AND DATE(po.order_date) <= DATE(#{filter.dateTo})
AND branch_id IN
#{id}
AND po.created_by = #{filter.createBy} ;

SELECT purchase_receive_results.id AS id, 'Purchase Receive' AS type, purchase_receive_results.code AS code, (po.total_amount - po.discount_amount + po.total_vat) AS amount, pr.received_date AS date, pr.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.created_by) AS createdBy, pr.modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.modified_by) AS modifiedBy, pr.status AS statusNum FROM purchase_receives pr INNER JOIN purchase_orders po ON po.id = pr.purchase_order_id INNER JOIN purchase_receive_results ON purchase_receive_results.id = pr.purchase_receive_result_id WHERE 1
AND DATE(pr.received_date) >= DATE(#{filter.dateFrom}) AND DATE(pr.received_date) <= DATE(#{filter.dateTo})
AND pr.branch_id IN
#{id}
AND pr.created_by = #{filter.createBy} ;

SELECT pr.id AS id, 'Bill Return' AS type, pr.pr_code AS code, (pr.total_amount + pr.total_vat) AS amount, pr.order_date AS date, pr.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.created_by) AS created_name, pr.modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.modified_by) AS modifiedBy, pr.status AS statusNum FROM purchase_returns pr WHERE 1
AND DATE(pr.order_date) >= DATE(#{filter.dateFrom}) AND DATE(pr.order_date) <= DATE(#{filter.dateTo})
AND pr.branch_id IN
#{id}
AND pr.created_by = #{filter.createBy} ;

SELECT pr.id AS id, 'Pay Bill' AS type, pr.reference AS code, (SELECT IFNULL(SUM(paid), 0) FROM pay_bill_details WHERE pay_bill_id = pr.id) AS amount, pr.date AS date, pr.created AS created, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.created_by) AS created_name, pr.modified, (SELECT CONCAT(users.first_name, ' ', users.last_name) FROM users WHERE id = pr.modified_by) AS modifiedBy, pr.is_active AS statusNum FROM pay_bills pr WHERE 1
AND DATE(pr.date) >= DATE(#{filter.dateFrom}) AND DATE(pr.date) <= DATE(#{filter.dateTo})
AND pr.branch_id IN
#{id}
AND pr.created_by = #{filter.createBy} ;

SELECT sales_orders.id AS id, 'Invoice' AS type, sales_orders.order_date AS date, sales_orders.due_date AS dueDate, branches.name AS branchName, branches.id AS branchId, sales_orders.so_code AS invoiceNo, sales_orders.customer_po_number AS customerPoNumber, CONCAT_WS(' - ', customers.customer_code, customers.name) AS customerName, customers.customer_code AS customerId, payment_terms.name AS terms, (DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) AS aging, sales_orders.balance AS openBalance FROM sales_orders LEFT JOIN customers ON customers.id = sales_orders.customer_id LEFT JOIN payment_terms ON payment_terms.id = sales_orders.payment_term_id LEFT JOIN branches ON branches.id = sales_orders.branch_id WHERE sales_orders.status > 0 AND sales_orders.balance > 0
AND (DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) >= #{fromValue} AND (DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) <= #{toValue}
AND (DATEDIFF(#{filter.date}, sales_orders.order_date) - payment_terms.net_days) >= #{toValue}
AND sales_orders.branch_id IN
#{branchId}
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.location_group_id = #{filter.groupId}
ORDER BY sales_orders.due_date ASC

SELECT sales_orders.id AS id, 'Invoice' AS type, sales_orders.order_date AS date, sales_orders.due_date AS dueDate, branches.name AS branchName, branches.id AS branchId, sales_orders.so_code AS invoiceNo, sales_orders.customer_po_number AS customerPoNumber, CONCAT_WS(' - ', customers.customer_code, customers.name) AS customerName, customers.customer_code AS customerId, payment_terms.name AS terms, (DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) AS netDays, sales_orders.balance AS openBalance FROM sales_orders LEFT JOIN customers ON customers.id = sales_orders.customer_id LEFT JOIN payment_terms ON payment_terms.id = sales_orders.payment_term_id LEFT JOIN branches ON branches.id = sales_orders.branch_id WHERE sales_orders.status > 0 AND sales_orders.balance > 0
AND ABS(DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) >= #{fromNetDay} AND ABS(DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) <= #{toNetDay}
AND ABS(DATEDIFF(#{filter.date}, sales_orders.order_date) - IFNULL(payment_terms.net_days, 0)) >= #{fromNetDay}
AND sales_orders.branch_id IN
#{branchId}
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.location_group_id = #{filter.groupId}
ORDER BY payment_terms.net_days ASC, sales_orders.due_date ASC

SELECT po.id AS id, 'Bill' AS type, po.order_date AS date, po.due_date AS dueDate, branches.name AS branchName, branches.id AS branchId, po.po_code AS invoiceNo, CONCAT_WS(' - ', v.vendor_code, v.name) AS vendorName, v.vendor_code AS vendorId, payment_terms.name AS terms, payment_terms.net_days AS netDays, po.balance AS openBalance FROM purchase_orders po LEFT JOIN vendors v ON v.id = po.vendor_id LEFT JOIN payment_terms ON payment_terms.id = v.payment_term_id LEFT JOIN branches ON branches.id = po.branch_id WHERE po.status > 0 AND po.balance > 0
AND ABS(DATEDIFF(#{filter.date}, po.order_date) - IFNULL(payment_terms.net_days, 0)) >= #{fromNetDay} AND ABS(DATEDIFF(#{filter.date}, po.order_date) - IFNULL(payment_terms.net_days, 0)) <= #{toNetDay}
AND ABS(DATEDIFF(#{filter.date}, po.order_date) - IFNULL(payment_terms.net_days, 0)) >= #{fromNetDay}
AND po.branch_id IN
#{branchId}
AND po.vendor_id = #{filter.vendorId}
AND po.location_group_id = #{filter.groupId}
AND po.company_id IN ( SELECT company_id FROM user_companies WHERE user_id = #{filter.userId} )
ORDER BY payment_terms.net_days ASC, po.due_date ASC

SELECT sales_orders.id AS id, 'invoice' AS type, sales_orders.order_date AS date, sales_orders.due_date AS duDate, branches.name AS branchName, branches.id AS branchId, sales_orders.so_code AS invoiceNo, CONCAT_WS(' - ', customers.customer_code, customers.name) AS customerName, customers.customer_code AS customerId, payment_terms.name AS terms, DATEDIFF(NOW(), sales_orders.due_date) AS aging, sales_orders.balance AS openBalance FROM sales_orders LEFT JOIN customers ON customers.id = sales_orders.customer_id LEFT JOIN payment_terms ON payment_terms.id = sales_orders.payment_term_id LEFT JOIN branches ON branches.id = sales_orders.branch_id WHERE sales_orders.status > 0 AND sales_orders.due_date <= #{filter.date} AND DATEDIFF(NOW(), sales_orders.order_date) >= #{toValue}
AND sales_orders.branch_id IN
#{branchId}
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.location_group_id = #{filter.groupId}

SELECT
customers.id AS customerId,
customers.name AS customerName,
SUM(sales_orders.balance) AS amount
FROM sales_orders
LEFT JOIN customers ON customers.id = sales_orders.customer_id
WHERE sales_orders.status > 0 AND sales_orders.balance > 0

    AND sales_orders.branch_id IN

        #{branchId}



    AND sales_orders.due_date <= DATE(#{filter.date})


    AND sales_orders.customer_id = #{filter.organizationId}


    AND sales_orders.location_group_id = #{filter.groupId}

GROUP BY sales_orders.customer_id;

SELECT CONCAT_WS(' - ', v.vendor_code, v.name) AS vendorName, v.id AS vendorId, SUM(po.balance) AS amount FROM purchase_orders po INNER JOIN vendors v ON v.id = po.vendor_id LEFT JOIN payment_terms pt ON pt.id = v.payment_term_id LEFT JOIN branches b ON b.id = po.branch_id WHERE po.status >0 AND po.balance > 0
AND sales_orders.branch_id IN
#{branchId}
AND po.due_date <= DATE(#{filter.date})
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.location_group_id = #{filter.groupId}
GROUP BY po.vendor_id;

SELECT po.id AS id, 'Bill' AS type, po.order_date AS date, po.due_date AS dueDate, b.name AS branchName, b.id AS branchId, po.po_code AS invoiceNo, CONCAT_WS(' - ', v.vendor_code, v.name) AS vendorName, v.vendor_code AS vendorId, pt.name AS terms, (DATEDIFF(#{filter.date}, po.order_date) - pt.net_days) AS aging, po.balance AS openBalance, po.note AS note FROM purchase_orders po LEFT JOIN vendors v ON v.id = po.vendor_id LEFT JOIN payment_terms pt ON pt.id = v.payment_term_id LEFT JOIN branches b ON b.id = po.branch_id WHERE po.status > 0 AND po.balance > 0
AND (DATEDIFF(#{filter.date}, po.order_date) - pt.net_days) >= #{fromValue} AND (DATEDIFF(#{filter.date}, po.order_date) - pt.net_days ) <= #{toValue}
AND (DATEDIFF(#{filter.date}, po.order_date) - pt.net_days) >= #{toValue}
AND po.branch_id IN
#{branchId}
AND po.vendor_id = #{filter.vendorId}
AND po.location_group_id = #{filter.groupId}
ORDER BY po.order_date ASC

SELECT po.id AS id, 'Bill' AS type, po.order_date AS date, po.due_date AS dueDate, b.name AS branchName, b.id AS branchId, po.po_code AS PBNo, CONCAT_WS(' - ', v.vendor_code, v.name) AS vendorName, v.id AS vendorId, pt.name AS terms, DATEDIFF(NOW(), po.order_date) AS aging, po.balance AS openBalance, po.note AS note FROM purchase_orders po INNER JOIN vendors v ON v.id = po.vendor_id LEFT JOIN payment_terms pt ON pt.id = v.payment_term_id LEFT JOIN branches b ON b.id = po.branch_id WHERE po.order_date <=#{filter.date} AND po.status > 0 AND DATEDIFF(NOW(), po.order_date) >= #{toValue}
AND sales_orders.branch_id IN
#{branchId}
AND sales_orders.customer_id = #{filter.organizationId}
AND sales_orders.location_group_id = #{filter.groupId}

SELECT SUM(debit) AS debit, SUM(credit) AS credit, `date` AS date, chart_account_id AS chartAccountId, company_id AS companyId, location_id AS locationId, customer_id AS customerId, vendor_id AS vendorId, employee_id AS employeeId, other_id AS otherId, class_id AS classId FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE gl.is_approve = 1 AND gl.is_active = 1 AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId}) AND is_retained_earnings = 0
AND DATE(gl.date) >= #{filter.dateFrom}
AND DATE(gl.date) <= #{filter.dateTo}
GROUP BY `date`, chart_account_id, company_id, location_id, customer_id, vendor_id, employee_id, other_id, class_id

mapper.sql:
IFNULL(
(
SELECT  SUM(debit) FROM general_ledger_detail_bl_#{filter.userId}
WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id)

    AND DATE(date) >= #{filter.dateFrom}


    AND DATE(date) <= #{filter.dateTo}


    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


    AND other_id = #{filter.other}


    AND class_id = #{filter.classId}

) - (
SELECT SUM(credit)  FROM general_ledger_detail_bl_#{filter.userId}
WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id)

    AND DATE(date) >= #{filter.dateFrom}


    AND DATE(date) <= #{filter.dateTo}


    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


    AND other_id = #{filter.other}


    AND class_id = #{filter.classId}

)
, 0) * -1 AS totalAmount

IFNULL(
(
SELECT SUM(debit) FROM general_ledger_detail_bl_#{filter.userId}
WHERE chart_account_id = chart_accounts.id
AND date >= #{filter.dateFrom} AND date <= #{filter.dateTo}

    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


    AND other_id = #{filter.other}


    AND class_id = #{filter.classId}

) - (
SELECT SUM(credit)  FROM general_ledger_detail_bl_#{filter.userId}
WHERE chart_account_id = chart_accounts.id
AND date >= #{filter.dateFrom} AND date <= #{filter.dateTo}

    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


