SELECT months.date, SUM( IFNULL( (SELECT SUM(credit) FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id) AND gl.is_approve = 1 AND gl.is_active = 1 AND DATE_FORMAT(gl.date, '%Y-%m') = DATE_FORMAT(months.date, '%Y-%m')
), 0 ) - IFNULL( (SELECT SUM(debit) FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id = gld.general_ledger_id WHERE gld.chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id) AND gl.is_approve = 1 AND gl.is_active = 1 AND DATE_FORMAT(gl.date, '%Y-%m') = DATE_FORMAT(months.date, '%Y-%m')
), 0 ) ) AS totalAmount FROM ( SELECT DATE_FORMAT(DATE_ADD(#{filter.dateFrom}, INTERVAL month_num.n MONTH), '%Y-%m-01') AS date FROM ( SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 ) month_num WHERE DATE_ADD(#{filter.dateFrom}, INTERVAL month_num.n MONTH) <= #{filter.dateTo} ) months CROSS JOIN chart_account_groups g INNER JOIN chart_account_types t ON g.chart_account_type_id = t.id WHERE g.is_active = 1 AND t.name IN ('Income','Other Income','Cost of Goods Sold','Expense','Other Expense') GROUP BY months.date ORDER BY months.date

