SELECT gl.id AS id, gld.type AS typeName, cus.id AS customerId, CASE WHEN gld.customer_id IS NOT NULL THEN COALESCE(cus.name, '') WHEN gld.vendor_id IS NOT NULL THEN (SELECT name FROM vendors WHERE id=gld.vendor_id) WHEN gld.employee_id IS NOT NULL THEN (SELECT name FROM employees WHERE id=gld.employee_id) WHEN gld.other_id IS NOT NULL THEN (SELECT name FROM others WHERE id=gld.employee_id) ELSE "" END AS customerName, gl.date AS date, gl.reference AS reference, gld.is_reconcile AS clear, (gld.credit*-1) AS amount FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id LEFT JOIN customers AS cus ON cus.id = gld.customer_id WHERE credit>0 AND gl.is_active=1 AND gl.is_approve=1 AND gld.is_reconcile=1 AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = 1)
AND gld.chart_account_id=#{filter.chartAccountId}
AND gld.reconcile_id=#{filter.ReconcileDateId}
AND gld.branch_id IN
#{branchId}
ORDER BY date ASC, gl.id ASC

SELECT gl.id AS id, gld.type AS typeName, cus.id AS customerId, CASE WHEN gld.customer_id IS NOT NULL THEN COALESCE(cus.name, '') WHEN gld.vendor_id IS NOT NULL THEN (SELECT name FROM vendors WHERE id=gld.vendor_id) WHEN gld.employee_id IS NOT NULL THEN (SELECT name FROM employees WHERE id=gld.employee_id) WHEN gld.other_id IS NOT NULL THEN (SELECT name FROM others WHERE id=gld.employee_id) ELSE "" END AS customerName, gl.date AS date, gl.reference AS reference, gld.is_reconcile AS clear, gld.debit AS amount FROM general_ledgers gl INNER JOIN general_ledger_details gld ON gl.id=gld.general_ledger_id LEFT JOIN customers AS cus ON cus.id = gld.customer_id WHERE debit>0 AND gl.is_active=1 AND gl.is_approve=1 AND gld.is_reconcile=1 AND gld.company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{filter.userId})
AND gld.chart_account_id=#{filter.chartAccountId}
AND gld.reconcile_id=#{filter.ReconcileDateId}
AND gld.branch_id IN
#{branchId}
ORDER BY date ASC, gl.id ASC
